$ErrorActionPreference='Stop'
$taskProject=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$taskSource="$taskProject/translation-source";$taskData="$taskProject/src/main/resources/data/witherskyru"
$taskBefore=@{};$taskAfter=@{};$taskOldSources=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$taskNewSources=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
foreach($taskFile in (Get-ChildItem $taskData -Filter '*.json')){foreach($taskRow in (Get-Content $taskFile.FullName -Raw|ConvertFrom-Json).records){if(!$taskRow.source -or !$taskRow.speaker -or $taskRow.source -notmatch '^\[NPC\] '){continue};[void]$taskNewSources.Add($taskRow.source);if(!$taskAfter.ContainsKey($taskRow.speaker)){$taskAfter[$taskRow.speaker]=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)};[void]$taskAfter[$taskRow.speaker].Add($taskRow.source);if($taskFile.Name -eq 'npc-expansion76.json'){continue};[void]$taskOldSources.Add($taskRow.source);if(!$taskBefore.ContainsKey($taskRow.speaker)){$taskBefore[$taskRow.speaker]=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)};[void]$taskBefore[$taskRow.speaker].Add($taskRow.source)}}
$taskRuntime=Get-Content "$taskSource/NPC_RETAINED_RUNTIME_0.15.74.json" -Raw|ConvertFrom-Json
$taskRuntimeSources=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($taskRow in $taskRuntime.records){[void]$taskRuntimeSources.Add($taskRow.source)}
$taskIndex=Get-Content "$taskSource/NPC_INDEX_0.15.74.json" -Raw|ConvertFrom-Json;$taskFresh=Get-Content "$taskSource/NPC_SOURCES_0.15.76.json" -Raw|ConvertFrom-Json
$taskPrevious75=Get-Content "$taskSource/NPC_SOURCES_0.15.75.json" -Raw|ConvertFrom-Json;$taskPrevious74=Get-Content "$taskSource/NPC_SOURCES_0.15.74.json" -Raw|ConvertFrom-Json
$taskPrior=@{pages=@($taskPrevious75.pages)+@($taskPrevious74.pages)}
$taskClassified=Get-Content "$taskSource/NPC_CANDIDATES_0.15.76.json" -Raw|ConvertFrom-Json
$taskOther=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($taskRow in (Get-Content "$taskData/npc-expansion76.json" -Raw|ConvertFrom-Json).records){if($taskRow.tag -eq 'SECURITY'){[void]$taskOther.Add($taskRow.source)}}
$taskPages=@{pages=@($taskFresh.pages)+@($taskPrior.pages|Where-Object name -notin $taskFresh.pages.name)}
# Index/other prior sections are the frozen2026-10-15 corpus,not newly obtained live scripts.
$taskSnapshotDates=@{index='2026-10-15';new_sections='2026-10-16';previous75_sections='2026-10-16';previous74_sections='2026-10-15'}
$taskAliases=@{'Mine Merchant'='Mining Merchant';'Maddox the Slayer'='Maddox';'Bingo (NPC)'='Bingo';'Bazaar (NPC)'='Bazaar';'Security Sloth'='Sloth'}
$taskPageBySpeaker=@{};foreach($taskPage in $taskPages.pages){$taskPageBySpeaker[$taskPage.name]=$taskPage}
$taskNames=@{};foreach($taskGroup in $taskIndex.groups){foreach($taskName in $taskGroup.names){if(!$taskNames.ContainsKey($taskName)){$taskNames[$taskName]=[Collections.Generic.List[string]]::new()};$taskNames[$taskName].Add($taskGroup.group)}}
$taskRegistry=@();foreach($taskName in ($taskNames.Keys|Sort-Object)){
 $taskSpeaker=if($taskAliases.ContainsKey($taskName)){$taskAliases[$taskName]}else{$taskName};$taskGroups=@($taskNames[$taskName]);$taskCountBefore=if($taskBefore.ContainsKey($taskSpeaker)){$taskBefore[$taskSpeaker].Count}else{0};$taskCountAfter=if($taskAfter.ContainsKey($taskSpeaker)){$taskAfter[$taskSpeaker].Count}else{0}
 $taskOtherCount=if($taskName -eq 'Security Sloth'){$taskOther.Count}else{0}
 $taskRegistry+=@{exact_other_tag_rows_after=$taskOtherCount;name=$taskName;runtime_speaker_alias=$taskSpeaker;groups=$taskGroups;historical_group_present=('Removed/historical' -in $taskGroups);exact_rows_before=$taskCountBefore;exact_rows_after=$taskCountAfter;published_section_in_combined_snapshot=$taskPageBySpeaker.ContainsKey($taskSpeaker);new_section_retrieved_this_batch=($taskSpeaker -in $taskFresh.pages.name);pending_bodies_rechecked_this_batch=$false;status=if($taskCountAfter){'EXACT_ROWS_PRESENT_NOT_COMPLETE_BRANCH_PROOF'}elseif($taskOtherCount){'EXACT_OTHER_TAG_PRESENT_NOT_COMPLETE_BRANCH_PROOF'}else{'NO_EXACT_ROW_IN_RESOURCE_UNION_DYNAMIC_OR_OTHER_HANDLERS_NOT_EXCLUDED'};all_branches_verified=$false}
}
$taskDetailed=@();foreach($taskPage in $taskPages.pages){
 $taskSection=$taskPage.section;$taskHistorical='';$taskStop=switch($taskPage.name){'Christopher'{'Disabled'}'Gladiator'{"First Interaction`n0.1"}'Clerk Seraphine'{"None`n4-5 April 2021"}default{$null}}
 if($taskStop -and $taskSection.Contains($taskStop)){$taskAt=$taskSection.IndexOf($taskStop);$taskHistorical=$taskSection.Substring($taskAt);$taskSection=$taskSection.Substring(0,$taskAt)}
 $taskCandidates=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$taskVariable=@();$taskAmbiguous=@();$taskNeutral=@()
 foreach($taskLine in ($taskSection -split "`n")){
  foreach($taskMatch in [regex]::Matches($taskLine,'\[NPC\] ([^:]{1,60}): (.*?)(?=\[NPC\]|$)')){
   $taskValue=$taskMatch.Value.TrimEnd();$taskValue=($taskValue -split 'Select an option:',2)[0].TrimEnd();$taskValue=($taskValue -split '\[(?:SHOW ABIPHONE|GIVE ITEM|GIVE PETS|HAND OVER FANCY DRINKS|PAY 10 MILLION COINS|ATTEMPT CHALLENGE)\]',2)[0].TrimEnd()
   if($taskValue.Contains('Susan will repeatedly')){$taskValue=$taskValue.Substring(0,$taskValue.IndexOf('Susan will repeatedly')).TrimEnd()}
   $taskValue=($taskValue -split '✆ [^:]{1,60} has been added to your Abiphone',2)[0].TrimEnd()
   if($taskValue -match '\[[Pp]layer\]|<[^>]+>|<number>|#th|\[pet\]|\[Bundle Name\]|\[time\]|\[potion effect\]|✆ #,'){$taskVariable+=@{source=$taskValue;status='PUBLISHED_VARIABLE_NOT_LITERAL_SERVER_KEY'};continue}
   if($taskValue -match ': ✆ \.{3}(?: \.{3})?$'){$taskNeutral+=@{source=$taskValue;status='LANGUAGE_NEUTRAL_NO_TRANSLATION_NEEDED'};continue}
   if($taskPage.name -eq 'Shifty' -and $taskValue.EndsWith('✆ Look...')){$taskAmbiguous+=@{source=$taskValue;status='UNPREFIXED_CONTINUATION_BOUNDARY_UNVERIFIED'};continue}
   if($taskPage.name -eq 'Carpenter' -and $taskValue.EndsWith('Some furniture is available exclusively in the Furniture Shop downstairs.')){$taskAmbiguous+=@{source=$taskValue;unprefixed_continuation='Check it out!';status='UNPREFIXED_CONTINUATION_BOUNDARY_UNVERIFIED'};continue}
   [void]$taskCandidates.Add($taskValue)
  }
 }
 if($taskPage.name -in $taskClassified.pages.speaker){
  $taskRecorded=$taskClassified.pages|Where-Object speaker -ceq $taskPage.name
  $taskCandidates=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($taskKey in @($taskRecorded.registered_before)+@($taskRecorded.without_exact_registration)){[void]$taskCandidates.Add($taskKey)}
  $taskVariable=@($taskRecorded.published_variable_definitions);$taskAmbiguous=@($taskRecorded.ambiguous_excluded);$taskHistorical=if($taskRecorded.historical_section_excluded){'explicit historical section excluded'}else{''}
 }
 $taskSupportedBefore=@($taskCandidates|Where-Object {$taskOldSources.Contains($_) -or $taskRuntimeSources.Contains($_)})
 $taskSupportedAfter=@($taskCandidates|Where-Object {$taskNewSources.Contains($_) -or $taskOther.Contains($_) -or $taskRuntimeSources.Contains($_)})
 $taskMissing=@($taskCandidates|Where-Object {!$taskNewSources.Contains($_) -and !$taskOther.Contains($_) -and !$taskRuntimeSources.Contains($_)}|Sort-Object)
 $taskDetailed+=@{speaker=$taskPage.name;source_url=$taskPage.url;section_retrieved=($taskPage.section -ne 'MISSING SECTION');published_literal_candidates=$taskCandidates.Count;registered_before=$taskSupportedBefore.Count;registered_after=$taskSupportedAfter.Count;without_exact_registration=$taskMissing;published_variable_definitions=$taskVariable;ambiguous_boundaries=$taskAmbiguous;language_neutral=$taskNeutral;historical_section_excluded=[bool]$taskHistorical;scope='Finite retrieved publication snapshot,not live server channel/colour/branch completeness. Missing exact key may be handled dynamically.';all_live_branches_verified=$false}
}
$taskNew=Get-Content "$taskData/npc-expansion76.json" -Raw|ConvertFrom-Json
$taskNewlyRepresented=@($taskNew.records.speaker|Sort-Object -Unique|Where-Object {!$taskBefore.ContainsKey($_)})
$taskOverview=@{version='0.15.76-dev';date='2026-10-16';snapshot_dates=$taskSnapshotDates;scope='Community navigation index and55 finite published dialogue sections;not complete/current server registry,all script denominators,player-authored Island NPC text or live style capture';indexed_unique_names=$taskRegistry.Count;indexed_group_memberships=@($taskIndex.groups.names).Count;explicit_historical_group_names=@(($taskIndex.groups|Where-Object group -eq 'Removed/historical').names).Count;exact_unique_sources_before=$taskOldSources.Count;exact_unique_sources_after=$taskNewSources.Count;exact_speakers_before=$taskBefore.Count;exact_speakers_after=$taskAfter.Count;new_exact_rows=$taskNew.records.Count;new_exact_npc_rows=@($taskNew.records|Where-Object tag -eq 'NPC').Count;new_exact_security_rows=$taskOther.Count;exact_other_tag_unique_sources_after=$taskOther.Count;exact_any_recorded_tag_sources_after=($taskNewSources.Count+$taskOther.Count);exact_any_recorded_tag_speakers_after=($taskAfter.Count+1);new_exact_row_speakers=@($taskNew.records.speaker|Sort-Object -Unique).Count;newly_represented_speakers=$taskNewlyRepresented;indexed_names_with_some_exact_rows_before=@($taskRegistry|Where-Object exact_rows_before -gt 0).Count;indexed_names_with_some_exact_rows_after=@($taskRegistry|Where-Object exact_rows_after -gt 0).Count;indexed_names_without_exact_rows_after=@($taskRegistry|Where-Object exact_rows_after -eq 0).Count;indexed_names_without_any_recorded_tag_rows_after=@($taskRegistry|Where-Object {($_.exact_rows_after+$_.exact_other_tag_rows_after) -eq 0}).Count;full_server_untranslated_row_count=$null;all_npcs_translated=$false;registry=$taskRegistry;reviewed_pages=$taskDetailed}
[IO.File]::WriteAllText("$taskSource/NPC_AUDIT_0.15.76.json",($taskOverview|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false))
$taskLines=@('# Реестр проверки NPC — 0.15.76-dev','','Дата: 2026-10-16. Это рабочий список, а не заявление о полном переводе.','Числа ниже — точные уникальные ключи NPC из ресурсов; динамические обработчики не пересчитаны в фиктивные тысячи строк.','Индекс зафиксирован2026-10-15; новые17 разделов получены2026-10-16, прежние разделы сохранены с исходными датами.','Наличие перевода имени или нескольких реплик не означает проверки всей ветки.','Имена из группы Removed/historical не объявляются действующими. Полный серверный объём непереведённых строк неизвестен.','','| Показатель | До | После |','| --- | ---: | ---: |',"| Точные уникальные ключи NPC в ресурсах | $($taskOldSources.Count) | $($taskNewSources.Count) |","| Говорящие персонажи с точными строками | $($taskBefore.Count) | $($taskAfter.Count) |","| Названия из индекса, сопоставленные с точными строками | $($taskOverview.indexed_names_with_some_exact_rows_before) | $($taskOverview.indexed_names_with_some_exact_rows_after) |",'','## Сводный учёт опубликованных разделов','','17 новых разделов получены в76. Прежние38 разделов перенесены из74/75 без нового получения.','Основные счётчики выше — только тег NPC. Отдельно добавлена одна строка SECURITY у Sloth; общий итог всех этих тегов —1451, говорящих персонажей —136.','Для Taylor показан прежний нормальный раздел, не новые Alpha-реплики; см. NPC_REVIEW_NOTES_0.15.75.json.','«Без точной записи» — кандидаты, требующие дальнейшей проверки. Некоторые могут обслуживаться динамически.','Переменные, неоднозначные границы, нейтральные междометия и исторические ветки учитываются отдельно в JSON.','','| Персонаж | Опубликованные точные кандидаты | С записью до | С записью после | Без точной записи |','| --- | ---: | ---: | ---: | ---: |')
foreach($taskRow in $taskDetailed){if(!$taskRow.section_retrieved){$taskLines+='| '+$taskRow.speaker+' | раздел не получен | — | — | неизвестно |';continue};$taskLines+='| '+$taskRow.speaker+' | '+$taskRow.published_literal_candidates+' | '+$taskRow.registered_before+' | '+$taskRow.registered_after+' | '+$taskRow.without_exact_registration.Count+' |'}
$taskLines+=@('','## Все названия из навигационного индекса','','Источник: https://hypixelskyblock.minecraft.wiki/w/NPC','Статус «есть строки» не является знаком готовности NPC. Совпадающие имена в разных мирах требуют отдельной проверки.','','| Название | Разделы | Точных NPC-строк до | После | Других тегов | Статус |','| --- | --- | ---: | ---: | ---: | --- |')
foreach($taskRow in $taskRegistry){$taskLines+='| '+$taskRow.name.Replace('|','/')+' | '+($taskRow.groups -join '; ')+' | '+$taskRow.exact_rows_before+' | '+$taskRow.exact_rows_after+' | '+$taskRow.exact_other_tag_rows_after+' | '+$(if($taskRow.exact_rows_after){'есть строки; ветки не сертифицированы'}elseif($taskRow.exact_other_tag_rows_after){'есть строка SECURITY; ветки не сертифицированы'}else{'точных строк нет; требуется проверка'})+' |'}
[IO.File]::WriteAllLines("$taskSource/NPC_REGISTRY_0.15.76_RU.md",$taskLines,[Text.UTF8Encoding]::new($false))
